export function createSurfaceEditor(canvas,{read,onChange,onFile,onFocus}){
 const ctx=canvas.getContext('2d');let drag=null,frame=null,zoom=1,pan={x:0,y:0},lastProduct=null;
 const dims=()=>{const state=read();if(!state?.spec||!state.placement)return null;if(state.product?.id!==lastProduct){lastProduct=state.product?.id;zoom=1;pan={x:0,y:0}}const w=600,h=420,pad=40,scale=Math.min((w-pad*2)/state.spec.maxW,(h-pad*2)/state.spec.maxH)*zoom;return {...state,w,h,scale,cx:w/2-pan.x*scale,cy:h/2+pan.y*scale}};
 function boundary(d){const w=d.spec.maxW*d.scale,h=d.spec.maxH*d.scale;ctx.beginPath();if(d.spec.shape==='circle')ctx.arc(d.cx,d.cy,Math.min(w,h)/2,0,Math.PI*2);else ctx.rect(d.cx-w/2,d.cy-h/2,w,h)}
 function render(){const d=dims();if(!d)return;canvas.width=d.w;canvas.height=d.h;const p=d.placement;ctx.fillStyle='#f4f6ef';ctx.fillRect(0,0,d.w,d.h);boundary(d);ctx.fillStyle='#fff';ctx.fill();ctx.save();boundary(d);ctx.clip();ctx.strokeStyle='#edf0e6';ctx.lineWidth=1;for(let x=d.cx-d.spec.maxW*d.scale/2;x<d.cx+d.spec.maxW*d.scale/2;x+=10*d.scale){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,d.h);ctx.stroke()}for(let y=d.cy-d.spec.maxH*d.scale/2;y<d.cy+d.spec.maxH*d.scale/2;y+=10*d.scale){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(d.w,y);ctx.stroke()}ctx.translate(d.cx+p.x*d.scale,d.cy-p.y*d.scale);ctx.rotate(-p.angle*Math.PI/180);if(d.hasArtwork&&d.artCanvas)ctx.drawImage(d.artCanvas,-p.w*d.scale/2,-p.h*d.scale/2,p.w*d.scale,p.h*d.scale);ctx.restore();boundary(d);ctx.strokeStyle='#81966f';ctx.lineWidth=2;ctx.setLineDash([7,5]);ctx.stroke();ctx.setLineDash([]);
 ctx.save();ctx.translate(d.cx+p.x*d.scale,d.cy-p.y*d.scale);ctx.rotate(-p.angle*Math.PI/180);ctx.strokeStyle='#306b9a';ctx.lineWidth=2;ctx.strokeRect(-p.w*d.scale/2,-p.h*d.scale/2,p.w*d.scale,p.h*d.scale);for(const x of [-1,1])for(const y of [-1,1]){ctx.beginPath();ctx.arc(x*p.w*d.scale/2,y*p.h*d.scale/2,7,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.stroke()}ctx.beginPath();ctx.moveTo(0,-p.h*d.scale/2);ctx.lineTo(0,-p.h*d.scale/2-26);ctx.stroke();ctx.beginPath();ctx.arc(0,-p.h*d.scale/2-32,10,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.stroke();ctx.fillStyle='#306b9a';ctx.font='15px sans-serif';ctx.textAlign='center';ctx.fillText('↻',0,-p.h*d.scale/2-27);if(!d.hasArtwork){ctx.fillStyle='#7c8d73';ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText('Drop artwork here',0,0)}ctx.restore();
 if(d.spec.shape==='wrap'){ctx.font='15px sans-serif';ctx.fillStyle='#798a72';ctx.textAlign='center';ctx.fillText('BACK',d.cx-d.spec.maxW*d.scale*.32,d.cy+d.spec.maxH*d.scale/2+27);ctx.fillText('OPPOSITE HANDLE',d.cx,d.cy+d.spec.maxH*d.scale/2+27);ctx.fillText('FRONT',d.cx+d.spec.maxW*d.scale*.32,d.cy+d.spec.maxH*d.scale/2+27)}
 const name=d.spec.surfaceName||((d.side==='back'?'Back':'Front')+' print panel');document.getElementById('mapCaption').textContent=name+' · '+d.spec.maxW+' × '+d.spec.maxH+' mm';canvas.setAttribute('aria-label',name+'. Drag artwork or a corner handle. Arrow keys move artwork; hold Shift for 5 mm steps.');
 }
 function point(e,d){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*d.w/r.width,y:(e.clientY-r.top)*d.h/r.height}}
 canvas.onpointerdown=e=>{const d=dims();if(!d)return;canvas.focus();const q=point(e,d),p=d.placement,dx=(q.x-d.cx)/d.scale-p.x,dy=(d.cy-q.y)/d.scale-p.y,a=-p.angle*Math.PI/180,lx=dx*Math.cos(a)-dy*Math.sin(a),ly=dx*Math.sin(a)+dy*Math.cos(a),corner=Math.abs(Math.abs(lx)-p.w/2)*d.scale<17&&Math.abs(Math.abs(ly)-p.h/2)*d.scale<17;
 const rotateHit=Math.hypot(lx*d.scale,(ly-p.h/2)*d.scale-32)<17;const outside=d.spec.shape==='circle'?Math.hypot((q.x-d.cx)/d.scale,(q.y-d.cy)/d.scale)>d.spec.maxW/2:Math.abs(q.x-d.cx)>d.spec.maxW*d.scale/2||Math.abs(q.y-d.cy)>d.spec.maxH*d.scale/2;const insideArtwork=Math.abs(lx)<=p.w/2&&Math.abs(ly)<=p.h/2;if(outside&&!insideArtwork&&!corner&&!rotateHit)return;drag={mode:rotateHit?'rotate':corner?'resize':'move',start:q,original:{...p},ratio:p.w/p.h};if(!rotateHit&&!corner&&(Math.abs(lx)>p.w/2||Math.abs(ly)>p.h/2)){const x=(q.x-d.cx)/d.scale,y=(d.cy-q.y)/d.scale;onChange({x,y});drag.original={...p,x,y}}canvas.setPointerCapture(e.pointerId);e.preventDefault()};
 canvas.onpointermove=e=>{if(!drag)return;const d=dims();if(!d)return;const q=point(e,d);let value;if(drag.mode==='rotate'){let a=Math.atan2((d.cy-q.y)/d.scale-d.placement.y,(q.x-d.cx)/d.scale-d.placement.x)*180/Math.PI-90;a=(a+540)%360-180;if(e.shiftKey)a=Math.round(a/15)*15;value={angle:a}}else if(drag.mode==='move')value={x:drag.original.x+(q.x-drag.start.x)/d.scale,y:drag.original.y-(q.y-drag.start.y)/d.scale};else{const dx=(q.x-d.cx)/d.scale-d.placement.x,dy=(d.cy-q.y)/d.scale-d.placement.y,a=-d.placement.angle*Math.PI/180;let w=Math.max(.1,2*Math.abs(dx*Math.cos(a)-dy*Math.sin(a))),h=Math.max(.1,2*Math.abs(dx*Math.sin(a)+dy*Math.cos(a)));if(document.getElementById('lockAspect').checked){h=w/drag.ratio}value={w,h}}cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{onChange(value);render()});e.preventDefault()};
 const end=()=>{drag=null};canvas.onpointerup=end;canvas.onpointercancel=end;
 canvas.onkeydown=e=>{const d=dims();if(!d)return;const n=e.shiftKey?5:1,v={ArrowLeft:[-n,0],ArrowRight:[n,0],ArrowUp:[0,n],ArrowDown:[0,-n]}[e.key];if(v){e.preventDefault();onChange({x:d.placement.x+v[0],y:d.placement.y+v[1]});render()}};
 canvas.ondragover=e=>{e.preventDefault();canvas.classList.add('drop-active')};canvas.ondragleave=()=>canvas.classList.remove('drop-active');canvas.ondrop=e=>{e.preventDefault();canvas.classList.remove('drop-active');onFile(e.dataTransfer.files[0])};document.getElementById('focusDesign').onclick=onFocus;document.getElementById('mapZoomIn').onclick=()=>{zoom*=1.25;render()};document.getElementById('mapZoomOut').onclick=()=>{zoom*=.8;render()};document.getElementById('fitPrintArea').onclick=()=>{zoom=1;pan={x:0,y:0};render()};document.getElementById('fitArtwork').onclick=()=>{const d=dims();if(!d)return;const p=d.placement,a=p.angle*Math.PI/180,w=Math.abs(p.w*Math.cos(a))+Math.abs(p.h*Math.sin(a)),h=Math.abs(p.w*Math.sin(a))+Math.abs(p.h*Math.cos(a));const x0=Math.min(-d.spec.maxW/2,p.x-w/2),x1=Math.max(d.spec.maxW/2,p.x+w/2),y0=Math.min(-d.spec.maxH/2,p.y-h/2),y1=Math.max(d.spec.maxH/2,p.y+h/2);pan={x:(x0+x1)/2,y:(y0+y1)/2};const base=Math.min(520/d.spec.maxW,340/d.spec.maxH);zoom=Math.min(520/(x1-x0),340/(y1-y0))/base;render()};canvas.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();zoom*=Math.exp(-e.deltaY*.002);render()}},{passive:false});render();return{render};
}
